#!/usr/bin/env python3
"""Source-backed design audit. Reads repository code, never production state."""
import html, json, subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
base=subprocess.check_output(['git','rev-parse','main'],cwd=ROOT,text=True).strip()
rows=[]
def row(feature, current, design, status, file, marker):
    source=subprocess.check_output(['git','show',f'{base}:{file}'],cwd=ROOT,text=True)
    assert marker in source, (file, marker)
    line=source[:source.index(marker)].count('\n')+1
    rows.append(dict(feature=feature,current=current,design=design,status=status,source=file,line=line))
row('Название и иконка','OpenConnect for Mac; оригинальная иконка с двумя маршрутами.','Исходный знак стоит в навигации и карточке подключения; пустое состояние использует Lucide folder-plus. Название OpenConnect for Mac сохранено.','Исправлено','app/make-app.sh','<key>CFBundleName</key>')
row('Необязательное имя','Name необязателен; если пусто, в меню используется имя файла.','Основная форма содержит адрес и пользователя. Адрес заменяет пустое имя; своё имя — в «Дополнительно». Это новое правило отображения, не уже внедрённое поведение рабочего клиента.','Новый UX','app/Sources/ocmac-app/Core/Profile.swift','if d.name.trimmed.isEmpty')
row('Адрес и идентификатор','Профиль определяется именем файла; URL и отображаемое имя — отдельные поля. Допускается адрес без https://.','Адрес используется как подпись, но не меняет ID. Создание/переименование .ocmac потребует адаптера к рабочему хранилищу.','Частично','app/Sources/ocmac-app/Core/Profile.swift','var fileName =')
row('Профиль при открытии','Редактор сейчас открывает первый файл, если выбор ещё отсутствует.','Активный → последний выбранный → первый доступный. Пока реализовано только в демо.','Новый UX','app/Sources/ocmac-app/UI/ProfileEditor.swift','if selected == nil, loadedName == nil, let first = files.first')
row('Сохранение профиля','Есть проверка ошибок, предупреждения, обнаружение внешних правок, разрешение конфликта и резервная копия.','Проверка полей, сохранение/отмена; отдельное состояние конфликта с перечитыванием и перезаписью. .bak и наблюдение за реальным файлом потребуют рабочего хранилища.','Экран и сценарий','app/Sources/ocmac-app/UI/ProfileEditor.swift','case changedOnDisk')
row('SSO','Страница организации в WKWebView; поля, шаги и подтверждения задаёт сервер. Приложение может подставлять данные по правилам.','Окна показывают пример серверной формы, а не обещают одинаковые пароль/код для любого VPN. Настоящего WebView и запросов в демо нет.','Частично','auth/Sources/ocmac-auth/WebAuth.swift','webView = WKWebView')
row('Пароль и SMS','Отдельный режим: пароль подставляется или запрашивается, код из SMS вводится вручную. Тихое переподключение недоступно.','Вход «Пароль и SMS» отделён от SSO; SMS не предлагается сохранять как TOTP.','Исправлено','app/Sources/ocmac-app/UI/ProfileEditor.swift','Пароль и код из SMS')
row('Предложение запомнить вход','При включённом «Запомнить, как я вхожу» после успешного входа предлагаются правила, пароль и источник кода.','Добровольная настройка TOTP после успешного входа. Добавлены отдельные правила и двухшаговая тестовая разметка. В production предложение зависит от Teach; новое размещение — предложение UX.','Новый UX','auth/Sources/ocmac-auth/Teach.swift','let offerCode = rec.code != nil')
row('Сохранение TOTP','Сохраняется секрет, не одноразовые цифры. В Teach секрет проверяется по введённому коду с допуском ± один период.','Убрана ошибочная запись шести цифр как настройки. Используются исходные TOTP.swift и QRImport.swift; проверка секрета воспроизводится на фиксированном тестовом времени.','Исправлено','auth/Sources/ocmac-auth/Teach.swift','static func matches(')
row('Отказ от TOTP / SMS','Человек может не менять источник либо выбрать SMS; без выбора секрет не записывается.','После входа можно пропустить настройку. В SMS-ветке предложение отсутствует. Демо не пишет Keychain.','Покрыто в демо','auth/Sources/ocmac-auth/Teach.swift','var codeMode = 0')
row('Варианты импорта TOTP','Настройки: QR с экрана, камера, ссылка или base32. Teach также читает файл QR. Парсер понимает экспорт Google Authenticator; HOTP для хранения не поддерживается.','Есть выбор экрана, камеры, файла, секрета/ссылки и записи из экспорта. Секрет проверяет реальный парсер; QR-получение имитируется, камера и экран не захватываются.','Экран и сценарий','app/Sources/ocmac-app/UI/ProfileEditor.swift','Button(L("Снять QR с экрана…"))')
row('Параметры TOTP','SHA1/SHA256/SHA512, 6–8 цифр, период 10–300 с. В Teach по голому ключу проверяются периоды 30/60.','Редактор алгоритма, 6–8 цифр и периода. Тестовый вход реально вычисляет код для выбранных параметров; отдельное состояние с 8 цифрами. Время зафиксировано для воспроизводимости.','Экран и сценарий','app/Sources/ocmac-app/Core/Profile.swift','static let totpAlgorithms')
row('Пароли: источники','auto, Keychain, KeePassXC, команда, ручной ввод.','Все пять источников, поля команды, записи/базы KeePassXC и сервиса мастер-пароля. Есть закрытая база. Реальные базы и команды не читаются и не запускаются.','Экран и сценарий','app/Sources/ocmac-app/Core/Profile.swift','static let passwordSources')
row('Коды: источники','auto, Keychain, KeePassXC, команда, SMS, отключено.','Все шесть источников, условные поля команд/KeePassXC, отдельные параметры TOTP. Для SMS и команды предложение записать секрет не появляется.','Экран и сценарий','app/Sources/ocmac-app/Core/Profile.swift','static let totpSources')
row('Запись секрета','Секрет сохраняется отдельным вызовом клиента, после сохранения самого профиля; не является полем .ocmac.','Редактор секрета доступен без несохранённых правок; тестовый результат меняется сразу, без кнопки сохранения профиля.','Исправлено','app/Sources/ocmac-app/Core/OCMacClient.swift','func savePassword(')
row('Режим сети','Два режима профиля: туннель с маршрутами/DNS и локальный SOCKS.','Туннель с выбранными сетями или двумя /1 для всего IPv4, и SOCKS. Предпросмотр файла записывает реальный Mode=tunnel/proxy, без выдуманного нового режима.','Экран и сценарий','app/Sources/ocmac-app/UI/ProfileEditor.swift','Text(L("Туннель"))')
row('Весь трафик','Сочетание 0.0.0.0/1 и 128.0.0.0/1. Это IPv4, не обещание маршрутизации IPv6.','Подпись исправлена на «Весь IPv4-трафик».','Исправлено','app/Sources/ocmac-app/UI/ProfileEditor.swift','«Всё в туннель»')
row('Split DNS','Каждая зона содержит имя, резолвер (IP или vpn) и порт; более длинная зона имеет приоритет.','Отдельный редактор домена, резолвера и порта; добавление/удаление зон, проверка ошибок, несколько зон. DNS доступен и при маршрутизации всего IPv4.','Экран и сценарий','app/Sources/ocmac-app/Core/Profile.swift','struct ZoneLine')
row('SOCKS','Порт по умолчанию 11080; системный SOCKS включается по желанию, чужой прокси не перезаписывается.','Порт исправлен на 11080. Предупреждение об отказе показано; реальных системных действий нет.','Частично','app/Sources/ocmac-app/Core/Profile.swift','var proxyPort = "11080"')
row('Прокси перед VPN','HTTP CONNECT / SOCKS5 без пароля; через него идут вход и VPN, DTLS выключается.','Добавлено поле существующего UpstreamProxy в «Дополнительно».','Покрыто в демо','app/Sources/ocmac-app/UI/ProfileEditor.swift','HTTP CONNECT или SOCKS5 без пароля')
row('Автоподключение','Общая политика manual / resume / always; исключение текущей сети по маршрутизатору. SMS-профили не предлагаются для always.','Выдуманный переключатель на профиле удалён. Политика и исключение сети перенесены в настройки приложения.','Исправлено','app/Sources/ocmac-app/UI/GeneralView.swift','Picker(L("Автоподключение")')
